cd "C:/Users/3D6B~1/AppData/Local/Temp/claude/C--visual-projects-game/5cebfb2a-057d-4fc7-8a6b-5129a86210ee/scratchpad/wol" && cat > tools/prefabs.py <<'EOF'
"""Dump MonoBehaviour serialized fields of Enemy/Boss/Player prefabs. Usage: prefabs.py <root>"""
import sys, os, re, json, csv, UnityPy
root = sys.argv[1]
SA = "C:/Program Files (x86)/Steam/steamapps/common/Wizard of Legend/WizardOfLegend_Data/StreamingAssets/core"
OUT = os.path.join(root, "data", "prefabs")
os.makedirs(OUT, exist_ok=True)
KEYS = ("/prefabs/enemies/", "/prefabs/bosses/", "/prefabs/player")
SKIP = {"m_GameObject", "m_Enabled", "m_Script", "m_Name", "lastAttack", "currentSurroundPoint",
        "myOrigin", "originalRotation", "originalScale"}

def is_pptr(v):
    return isinstance(v, dict) and "m_PathID" in v and "m_FileID" in v

def clean(v):
    if is_pptr(v):
        return None
    if isinstance(v, dict):
        if "_baseValue" in v and "_currentValue" in v:
            return v["_baseValue"]
        d = {}
        for k, x in v.items():
            if k in SKIP: continue
            c = clean(x)
            if c is not None and c != {} and c != []:
                d[k] = c
        return d
    if isinstance(v, list):
        l = [clean(x) for x in v]
        return [x for x in l if x is not None and x != {}]
    return v

env = UnityPy.load(SA)
by_pid = {}
paths = {}
for p, o in env.container.items():
    pl = "/" + p.lower()
    if p.endswith(".prefab") and any(k in pl for k in KEYS):
        paths[p] = o

def collect(go, prefix, out, depth=0):
    gname = go.m_Name
    for c in go.m_Components:
        try:
            comp = c.component.read() if hasattr(c, "component") else c.read()
        except Exception as e:
            out.append({"go": prefix + gname, "error": str(e)}); continue
        if comp.object_reader.type.name != "MonoBehaviour":
            continue
        try:
            cls = comp.m_Script.read().m_ClassName
            t = comp.object_reader.read_typetree()
            out.append({"go": prefix + gname, "class": cls, "fields": clean(t)})
        except Exception as e:
            out.append({"go": prefix + gname, "error": "%s: %s" % (type(e).__name__, e)})
    # children
    try:
        tr = go.m_Transform.read() if hasattr(go, "m_Transform") else None
        if tr is None:
            for c in go.m_Components:
                x = c.component.read() if hasattr(c, "component") else c.read()
                if x.object_reader.type.name in ("Transform", "RectTransform"):
                    tr = x; break
        for ch in tr.m_Children:
            cg = ch.read().m_GameObject.read()
            collect(cg, prefix + gname + "/", out, depth + 1)
    except Exception as e:
        out.append({"go": prefix + gname, "error": "children: %s" % e})

def first(comps, cls, key):
    for c in comps:
        if c.get("class") == cls or (cls == "*" and "fields" in c):
            f = c.get("fields", {})
            if key in f: return f[key]
    return ""

rows = []
fail = 0
for p, o in sorted(paths.items()):
    name = os.path.splitext(os.path.basename(p))[0]
    try:
        go = o.read()
        comps = []
        collect(go, "", comps)
        sub = "player" if "/player/" in p else ("bosses" if "/bosses/" in p else "enemies")
        d = {"path": p, "kind": sub, "components": comps}
        with open(os.path.join(OUT, name + ".json"), "w", encoding="utf-8") as f:
            json.dump(d, f, indent=1, ensure_ascii=False)
        errs = [c for c in comps if "error" in c]
        if errs: print("PARTIAL", name, errs[:2])
        # summary
        r = {"name": name, "kind": sub}
        for cls, key, col in [("Health", "healthStat", "maxHealth"), ("Health", "armorStat", "armor"),
                              ("Health", "evadeStat", "evade"), ("Health", "damageTakenStat", "damageTaken")]:
            r[col] = first(comps, cls, key)
        mv = [c for c in comps if c.get("class") == "Movement"]
        for k in ("moveSpeed", "baseMoveSpeed", "dashSpeed", "dashDuration", "dashRange"):
            for c in mv:
                if k in c["fields"]: r[k] = c["fields"][k]; break
        for k in ("alertRadius", "escapeRadius", "attackRadius", "surroundRadius", "alertNearbyEnemiesRadius", "maxAlertDistance", "element"):
            r[k] = first(comps, "*", k)
        # other numeric: min windup/exit/cooldown found anywhere
        wu, ex, cd = [], [], []
        def walk(v, key=""):
            if isinstance(v, dict):
                for k, x in v.items(): walk(x, k)
            elif isinstance(v, list):
                for x in v: walk(x, key)
            elif isinstance(v, (int, float)) and not isinstance(v, bool):
                kl = key.lower()
                if "windup" in kl and "id" not in kl and v > 0: wu.append(v)
                elif "exittime" in kl and v > 0: ex.append(v)
                elif "cooldown" in kl and v > 0: cd.append(v)
        for c in comps:
            if "fields" in c: walk(c["fields"])
        r["windupTimes"] = ";".join(str(round(x, 3)) for x in wu[:8])
        r["exitTimes"] = ";".join(str(round(x, 3)) for x in ex[:8])
        r["cooldowns"] = ";".join(str(round(x, 3)) for x in cd[:8])
        r["classes"] = ";".join(sorted({c["class"] for c in comps if "class" in c and c["class"] not in ("Health", "Movement", "SortSpriteLayer", "Fall", "MecanimEvents")}))
        rows.append(r)
    except Exception as e:
        fail += 1
        print("FAIL", name, type(e).__name__, e)
cols = []
for r in rows:
    for k in r:
        if k not in cols: cols.append(k)
with open(os.path.join(OUT, "summary.csv"), "w", newline="", encoding="utf-8") as f:
    w = csv.DictWriter(f, fieldnames=cols); w.writeheader(); w.writerows(rows)
print("dumped", len(rows), "failed", fail)
EOF
venv/Scripts/python.exe tools/prefabs.py . 2>&1 | tail -20; ls data/prefabs | wc -l

