            json.dump(d, f, indent=1, ensure_ascii=False)
        errs = [c for c in comps if "error" in c]
        if errs: print("PARTIAL", name, errs[:2])
        # summary
        r = {"name": name, "kind": sub}
        for cls, key, col in [("Health", "healthStat", "maxHealth"), ("Health", "armorStat", "armor"),
                              ("Health", "evadeStat", "evade"), ("Health", "damageTakenStat", "damageTaken")]:
            r[col] = first(comps, cls, key)
        mv = [c for c in comps if c.get("class") == "Movement"]
        for k in ("moveSpeed", "baseMoveSpeed", "dashSpeed", "dashDuration", "dashRange"):
            for c in mv:
                if k in c["fields"]: r[k] = c["fields"][k]; break
        for k in ("alertRadius", "escapeRadius", "attackRadius", "surroundRadius", "alertNearbyEnemiesRadius", "maxAlertDistance", "element"):
            r[k] = first(comps, "*", k)
        # other numeric: min windup/exit/cooldown found anywhere
        wu, ex, cd = [], [], []
        def walk(v, key=""):
            if isinstance(v, dict):
                for k, x in v.items(): walk(x, k)
            elif isinstance(v, list):
                for x in v: walk(x, key)
            elif isinstance(v, (int, float)) and not isinstance(v, bool):
                kl = key.lower()
                if "windup" in kl and "id" not in kl and v > 0: wu.append(v)
                elif "exittime" in kl and v > 0: ex.append(v)
                elif "cooldown" in kl and v > 0: cd.append(v)
        for c in comps:
            if "fields" in c: walk(c["fields"])
        r["windupTimes"] = ";".join(str(round(x, 3)) for x in wu[:8])
        r["exitTimes"] = ";".join(str(round(x, 3)) for x in ex[:8])
        r["cooldowns"] = ";".join(str(round(x, 3)) for x in cd[:8])
        r["classes"] = ";".join(sorted({c["class"] for c in comps if "class" in c and c["class"] not in ("Health", "Movement", "SortSpriteLayer", "Fall", "MecanimEvents")}))
        rows.append(r)
    except Exception as e:
        fail += 1
        print("FAIL", name, type(e).__name__, e)
cols = []
for r in rows:
    for k in r:
        if k not in cols: cols.append(k)
with open(os.path.join(OUT, "summary.csv"), "w", newline="", encoding="utf-8") as f:
    w = csv.DictWriter(f, fieldnames=cols); w.writeheader(); w.writerows(rows)
print("dumped", len(rows), "failed", fail)
